package net.fabricmc.fabric.api.client.screen.v1;
import java.util.Map;
import java.util.WeakHashMap;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;

/** Fabric API: mouse clicks/scrolls in a screen (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
public final class ScreenMouseEvents {
    private ScreenMouseEvents() {}

    /** Per-screen events, forgotten when the screen goes away. */
    private static final Map<Screen, Map<String, Event<?>>> PER_SCREEN = new WeakHashMap<>();

    @SuppressWarnings("unchecked")
    private static synchronized <T> Event<T> of(Screen s, String k, java.util.function.Supplier<Event<T>> f) {
        return (Event<T>) PER_SCREEN.computeIfAbsent(s, x -> new java.util.HashMap<>()).computeIfAbsent(k, x -> f.get());
    }

    /** Omniloader: drop a screen's per-screen listeners (Fabric does this each time a screen is set up again). */
    public static synchronized void clear(Screen s) { PER_SCREEN.remove(s); }

    /** Omniloader: the per-screen event if anyone registered on it. */
    @SuppressWarnings("unchecked")
    public static synchronized <T> Event<T> peek(Screen s, String k) { var m = PER_SCREEN.get(s); return m == null ? null : (Event<T>) m.get(k); }

    public static Event<AllowMouseClick> allowMouseClick(Screen forScreen) { return of(forScreen, "allowMouseClick", () -> EventFactory.createArrayBacked(AllowMouseClick.class, ls -> (screen, mouseX, mouseY, button) -> { for (AllowMouseClick l : ls) if (!l.allowMouseClick(screen, mouseX, mouseY, button)) return false; return true; })); }
    public static Event<BeforeMouseClick> beforeMouseClick(Screen forScreen) { return of(forScreen, "beforeMouseClick", () -> EventFactory.createArrayBacked(BeforeMouseClick.class, ls -> (screen, mouseX, mouseY, button) -> { for (BeforeMouseClick l : ls) l.beforeMouseClick(screen, mouseX, mouseY, button); })); }
    public static Event<AfterMouseClick> afterMouseClick(Screen forScreen) { return of(forScreen, "afterMouseClick", () -> EventFactory.createArrayBacked(AfterMouseClick.class, ls -> (screen, mouseX, mouseY, button) -> { for (AfterMouseClick l : ls) l.afterMouseClick(screen, mouseX, mouseY, button); })); }
    public static Event<AllowMouseRelease> allowMouseRelease(Screen forScreen) { return of(forScreen, "allowMouseRelease", () -> EventFactory.createArrayBacked(AllowMouseRelease.class, ls -> (screen, mouseX, mouseY, button) -> { for (AllowMouseRelease l : ls) if (!l.allowMouseRelease(screen, mouseX, mouseY, button)) return false; return true; })); }
    public static Event<BeforeMouseRelease> beforeMouseRelease(Screen forScreen) { return of(forScreen, "beforeMouseRelease", () -> EventFactory.createArrayBacked(BeforeMouseRelease.class, ls -> (screen, mouseX, mouseY, button) -> { for (BeforeMouseRelease l : ls) l.beforeMouseRelease(screen, mouseX, mouseY, button); })); }
    public static Event<AfterMouseRelease> afterMouseRelease(Screen forScreen) { return of(forScreen, "afterMouseRelease", () -> EventFactory.createArrayBacked(AfterMouseRelease.class, ls -> (screen, mouseX, mouseY, button) -> { for (AfterMouseRelease l : ls) l.afterMouseRelease(screen, mouseX, mouseY, button); })); }
    public static Event<AllowMouseScroll> allowMouseScroll(Screen forScreen) { return of(forScreen, "allowMouseScroll", () -> EventFactory.createArrayBacked(AllowMouseScroll.class, ls -> (screen, mouseX, mouseY, horizontalAmount, verticalAmount) -> { for (AllowMouseScroll l : ls) if (!l.allowMouseScroll(screen, mouseX, mouseY, horizontalAmount, verticalAmount)) return false; return true; })); }
    public static Event<BeforeMouseScroll> beforeMouseScroll(Screen forScreen) { return of(forScreen, "beforeMouseScroll", () -> EventFactory.createArrayBacked(BeforeMouseScroll.class, ls -> (screen, mouseX, mouseY, horizontalAmount, verticalAmount) -> { for (BeforeMouseScroll l : ls) l.beforeMouseScroll(screen, mouseX, mouseY, horizontalAmount, verticalAmount); })); }
    public static Event<AfterMouseScroll> afterMouseScroll(Screen forScreen) { return of(forScreen, "afterMouseScroll", () -> EventFactory.createArrayBacked(AfterMouseScroll.class, ls -> (screen, mouseX, mouseY, horizontalAmount, verticalAmount) -> { for (AfterMouseScroll l : ls) l.afterMouseScroll(screen, mouseX, mouseY, horizontalAmount, verticalAmount); })); }

    @FunctionalInterface public interface AllowMouseClick { boolean allowMouseClick(Screen screen, double mouseX, double mouseY, int button); }
    @FunctionalInterface public interface BeforeMouseClick { void beforeMouseClick(Screen screen, double mouseX, double mouseY, int button); }
    @FunctionalInterface public interface AfterMouseClick { void afterMouseClick(Screen screen, double mouseX, double mouseY, int button); }
    @FunctionalInterface public interface AllowMouseRelease { boolean allowMouseRelease(Screen screen, double mouseX, double mouseY, int button); }
    @FunctionalInterface public interface BeforeMouseRelease { void beforeMouseRelease(Screen screen, double mouseX, double mouseY, int button); }
    @FunctionalInterface public interface AfterMouseRelease { void afterMouseRelease(Screen screen, double mouseX, double mouseY, int button); }
    @FunctionalInterface public interface AllowMouseScroll { boolean allowMouseScroll(Screen screen, double mouseX, double mouseY, double horizontalAmount, double verticalAmount); }
    @FunctionalInterface public interface BeforeMouseScroll { void beforeMouseScroll(Screen screen, double mouseX, double mouseY, double horizontalAmount, double verticalAmount); }
    @FunctionalInterface public interface AfterMouseScroll { void afterMouseScroll(Screen screen, double mouseX, double mouseY, double horizontalAmount, double verticalAmount); }
}
